sys_script_include.script:
var checkApprovalHistory = Class.create();
checkApprovalHistory.prototype = {
    initialize: function() {},

    checkRecord: function(param) {
        var appH = new GlideRecord('u_approval_history');
        appH.addEncodedQuery('parent=' + param);
        appH.query();
        if (appH.hasNext()) {
            return true;
        } else {
            return false;
        }

    },
    checkBudget: function(sysID) {
        var appH = new GlideRecord('x_1040502_wbs_budget');
        appH.addEncodedQuery('wbs=' + sysID);
        appH.query();
        if (appH.hasNext()) {
            return false;
        } else {
            return true;
        }

    },
    // getBudgetFromWBS: function(sysID) {
    //     var details = [];
    // 	var obj = {};
    //     var bud = new GlideRecord('x_1040502_wbs_wbs');
    //     bud.addQuery('sys_id', sysID);
    //     bud.query();
    //     if (bud.next()) {
    //         obj.totalB = bud.u_total_budget;
    //         obj.year = bud.u_year;
    //     }
    //     details.push(obj);

    //     return details;

    // },

    checkApprover: function(sysID) {
        var val = new GlideRecord('sysapproval_approver');
        val.addEncodedQuery('state=requested^approver=' + gs.getUserID + '^document_id=' + sysID);
        val.query();
        if (val.hasNext()) {
            return true;
        } else {
            return false;
        }

    },
    checkHistoryRecord: function(param) {
        // var appH = new GlideRecord('x_1040502_nsc_pe_0_approval_routing_preview');
        //     appH.addEncodedQuery('parent=' + param);
        //     appH.query();
        //     var count = appH.getRowCount();
        //     // if (appH.hasnext()) {
        //         if (count >2) {
        //             return true;
        //         } else {
        //             return false;
        //         }
        // }

        var chngH = new GlideRecord('x_1040502_wbs_change_history');
        chngH.addEncodedQuery('budget=' + param);
        chngH.query();
        if (chngH.hasNext()) {
            return true;
        } else {
            return false;
        }
    },
	checkBudgetRecord: function(param) {

        var chngH = new GlideRecord('x_1040502_wbs_change_history');
        chngH.addEncodedQuery('budget=' + param);
        chngH.query();
        if (chngH.hasNext()) {
            return true;
        } else {
            return false;
        }
    },

    type: 'checkApprovalHistory'
};
